        vm.assume(caller != address(0));
        // Keep amount within reasonable bounds for funding; the bug relies on overflow.
        amount = bound(amount, 1, type(uint256).max / 2);

        // Fund the caller and call addToBalance with the given amount.
        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();

        // The invariant: after a deposit, the caller's balance must be at least the deposited amount.
