            assertEq(c.getBalance(caller), deposit1 + deposit2);
        } catch {
            // If it reverts, the reference contract would not have reverted
            // so we fail if the call reverted (reference never reverts)
            assertTrue(false, "Reference contract should never revert on addToBalance");
        }
    }
}

