pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 extraAmount, address actor) public {
        // Keep the domain wide but prevent overflow in total value to deposit.
        bound(amount, 0, type(uint128).max);
        bound(extraAmount, 0, type(uint128).max);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // Deposit two amounts to the same actor.
        vm.deal(actor, amount + extraAmount);
        vm.startPrank(actor);
        if (amount > 0) {
            c.addToBalance{value: amount}();
        }
        uint256 oldBalance = c.getBalance(actor);
        c.addToBalance{value: extraAmount}();
        uint256 newBalance = c.getBalance(actor);
        vm.stopPrank();

        // Withdraw must succeed returning the full amount.
        uint256 beforeWithdrawBalance = actor.balance;
        vm.prank(actor);
        try c.withdrawBalance() {
            uint256 received = actor.balance - beforeWithdrawBalance;
            // Assert: withdrawn amount equals the balance before withdrawal.
            assertEq(received, newBalance);
        } catch {
            fail("withdrawBalance reverted unexpectedly");
        }
    }
}

