import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialDeposit, uint256 attackerDeposit) public {
        // Keep amounts within reasonable bounds to avoid overflow, but fuzz widely
        vm.assume(initialDeposit > 0);
        vm.assume(attackerDeposit > 0);
        vm.assume(initialDeposit < type(uint128).max);
        vm.assume(attackerDeposit < type(uint128).max);

        // Deploy a re-entrant attacker that calls back into withdrawBalance
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // 1. An innocent user deposits some ETH
        address user = makeAddr("user");
        vm.deal(user, initialDeposit);
        vm.prank(user);
        c.addToBalance{value: initialDeposit}();

        // 2. The attacker deposits some ETH to have a balance
        vm.deal(address(attacker), attackerDeposit);
        attacker.addBalance{value: attackerDeposit}();

        // Record contract balance before withdraw
        uint256 balanceBefore = address(c).balance;

        // 3. Attacker calls withdrawBalance, which triggers re-entrancy
        attacker.attack();

        // Contract balance after the attack
        uint256 balanceAfter = address(c).balance;

        // In the reference C, the attacker can at most withdraw their own balance once.
        // Therefore, the contract should never lose more than the attacker's deposited amount.
        // In the buggy version, re-entrancy allows multiple withdrawals, breaking this invariant.
        assertTrue(balanceBefore - balanceAfter <= attackerDeposit);
    }
}

