pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 reenterAmount) public {
        // Restrict amounts so they don't overflow uint256 and addToBalance checks hold
        vm.assume(amount1 > 0 && amount1 <= type(uint128).max);
        vm.assume(amount2 > 0 && amount2 <= type(uint128).max);
        // Reentrant amount must be <= the balance deposited by the attacker, to trigger the bug
        vm.assume(reenterAmount > 0 && reenterAmount <= amount1);

        // Deploy a re-entrant attacker that will call withdrawBalance() during its receive()
        ReenteringAttacker attacker = new ReenteringAttacker(c, reenterAmount);
        address attackerAddr = address(attacker);

        // Fund attacker with ETH
        vm.deal(attackerAddr, amount1 + amount2);

        // Attacker deposits amount1 to C
        vm.prank(attackerAddr);
        c.addToBalance{value: amount1}();

        // Another user deposits amount2
        address otherUser = address(0x1234);
        vm.deal(otherUser, amount2);
        vm.prank(otherUser);
        c.addToBalance{value: amount2}();

        // Calculate expected contract balance after the attack: initial balance minus what the attacker should be able to withdraw
        uint256 contractBalBefore = address(c).balance;
        uint256 attackerBalanceBefore = c.getBalance(attackerAddr);
        uint256 otherBalanceBefore = c.getBalance(otherUser);

        // Attacker initiates withdraw via the helper, which re-enters
        vm.prank(attackerAddr);
        attacker.attack();

        uint256 contractBalAfter = address(c).balance;
        uint256 attackerBalanceAfter = c.getBalance(attackerAddr);
        uint256 otherBalanceAfter = c.getBalance(otherUser);

        // The invariant: contract ETH must equal sum of all user balances
        // Reference C satisfies this because balance is zeroed before external call,
        // limiting the re-entrant withdrawal to the original balance.
        // Mutant M zeroes balance after external call, so re-entrant withdrawal drains funds
        // without decreasing the attacker's balance, breaking the invariant.
        assertEq(contractBalAfter, attackerBalanceAfter + otherBalanceAfter);
    }
}

contract ReenteringAttacker {
    C public c;
    uint256 public reenterAmount;
    uint256 public reentryCount;

    constructor(C _c, uint256 _reenterAmount) {
        c = _c;
        reenterAmount = _reenterAmount;
    }

    function attack() external {
        // First withdraw; this will trigger receive() which calls withdrawBalance() again
        c.withdrawBalance();
    }

    receive() external payable {
        if (reentryCount == 0 && address(c).balance >= reenterAmount) {
            reentryCount++;
            // Re-entrant call to withdrawBalance before the original call resets the balance
            c.withdrawBalance();
        }
    }
}

